const C=window.Cheesie,$=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('vi-VN').format(n)+'đ';let size='M',selected={},kind='protein',folded=false,cart=[],category='favourites',lastFocus=null;const dialog=$('#dialog');
try{const saved=JSON.parse(localStorage.getItem('cheesie-cart-v1')||'[]');if(Array.isArray(saved))cart=saved.filter(r=>r&&typeof r.name==='string'&&typeof r.details==='string'&&Number.isInteger(r.price)&&r.price>=0&&Number.isInteger(r.qty)&&r.qty>0&&r.qty<=99&&typeof r.key==='string').slice(0,50)}catch{}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function svgContent(i){const c=i.color;switch(i.icon){case 'pork':return `<path d="M12 25Q5 12 22 10L43 17Q57 30 39 43L17 44Q8 38 12 25" fill="${c}" stroke="#82462f" stroke-width="2"/><path d="M15 24L40 30M18 16L42 22M18 35L33 38" stroke="#dfaa7d" stroke-width="4"/>`;case 'beef':return `<path d="M7 21Q13 7 29 14Q48 3 52 24L45 43Q25 55 9 39Z" fill="${c}" stroke="#582b20" stroke-width="2"/><path d="M14 23L42 19M16 31L43 28M19 39L39 35" stroke="#38251c" stroke-width="3" opacity=".7"/>`;case 'chicken':return `<path d="M10 19L22 9L41 12L52 26L42 45L20 49L8 34Z" fill="${c}" stroke="#ae6a27" stroke-width="2"/><path d="M17 19L24 17M31 23L40 21M15 32L22 29M30 38L39 35M42 29L46 26" stroke="#f0ba5d" stroke-width="4"/>`;case 'sausage':return `<g transform="rotate(-25 30 30)"><rect x="6" y="12" width="46" height="13" rx="6" fill="${c}" stroke="#833e2a" stroke-width="2"/><rect x="11" y="33" width="46" height="13" rx="6" fill="${c}" stroke="#833e2a" stroke-width="2"/><path d="M18 14L17 23M31 14L30 23M43 14L42 23M23 35L22 44M37 35L36 44" stroke="#dd9471" stroke-width="2"/></g>`;case 'sauce':return `<ellipse cx="30" cy="33" rx="25" ry="22" fill="#f6efdd" stroke="#c8b49a" stroke-width="2"/><ellipse cx="30" cy="29" rx="21" ry="17" fill="${c}"/><path d="M19 25Q29 18 38 25Q44 32 26 34" fill="none" stroke="#fff" stroke-width="3" opacity=".35"/>`;case 'bacon':return `<path d="M8 10Q20 17 30 10L52 14L47 24Q32 17 24 24L5 19ZM10 31Q22 38 31 31L54 35L48 46Q32 39 25 46L6 42Z" fill="${c}"/><path d="M8 14L49 19M10 36L49 41" stroke="#efb195" stroke-width="4"/>`;case 'egg':return `<path d="M29 6Q44 7 43 18Q58 20 53 36Q49 49 33 47Q15 56 9 41Q1 26 15 20Q12 7 29 6Z" fill="#fff9e8" stroke="#dfd1b2"/><circle cx="31" cy="29" r="12" fill="#efb52f"/><circle cx="27" cy="25" r="4" fill="#f9d56b"/>`;default:return `<path d="M8 13L47 8L54 45L15 52Z" fill="${c}" stroke="#d4af6b" stroke-width="2"/><circle cx="25" cy="24" r="4" fill="#d8a43e" opacity=".5"/><circle cx="40" cy="37" r="5" fill="#d8a43e" opacity=".5"/>`}}
function icon(i){return `<svg viewBox="0 0 60 60" aria-hidden="true">${svgContent(i)}</svg>`}
function open(html){lastFocus=document.activeElement;$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal()}
function close(){dialog.close();if(lastFocus?.isConnected)lastFocus.focus()}$('.close-dialog').onclick=close;dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});dialog.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus()});
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function saveCart(){localStorage.setItem('cheesie-cart-v1',JSON.stringify(cart));$('#bag-count').textContent=cart.reduce((n,r)=>n+r.qty,0)}
function addCart(row){const old=cart.find(r=>r.key===row.key);if(old){if(old.qty>=99)return toast('Tối đa 99 phần mỗi lựa chọn trong bản thử.');old.qty++}else cart.push({...row,qty:1});saveCart();toast('Đã thêm vào túi đồ ngon!')}
function chosen(k){return C.ingredients.filter(i=>i.kind===k&&selected[i.id]).map(i=>`${selected[i.id]>1?selected[i.id]+' × ':''}${i.name}`).join(', ')}
function update(){const s=C.sizes[size];$('#train-size').textContent=size;$('#next-stop').textContent=C.ready(size,selected)?'SẴN SÀNG LÊN TÀU':C.count(selected,'protein')<s.protein?'CHỌN NHÂN':'THÊM SỐT';$('#size-price').textContent=money(s.price);$('#sizes').innerHTML=Object.keys(C.sizes).map(k=>`<button data-size="${k}" class="${k===size?'selected':''}" aria-pressed="${k===size}">${k}<span>${C.sizes[k].protein} nhân · ${C.sizes[k].sauce} sốt</span></button>`).join('');document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>changeSize(b.dataset.size));$('#capacity').textContent=`${C.count(selected,'protein')}/${s.protein} nhân · ${C.count(selected,'sauce')}/${s.sauce} sốt`;$('#base-description').textContent=s.base.length?'Đã có trong giá size '+size+': '+s.base.join(' + ')+'.':'Size S: 1 phần nhân + 1 phần sốt. Topping thêm tính riêng.';$('#tray-help').textContent=kind==='extra'?'Topping tính riêng. Sốt thêm mở sau khi chọn đủ sốt của size.':`Đã chọn ${C.count(selected,kind)}/${s[kind]} phần ${kind==='protein'?'nhân':'sốt'} theo size ${size}.`;$('#ingredient-tray').setAttribute('aria-labelledby','tab-'+kind);renderTray();renderFood();const isReady=C.ready(size,selected);$('#ready-label').textContent=isReady?'SẴN SÀNG CUỐN':'ĐANG CHỌN';$('#selection-details').innerHTML=`<div class="selection-row"><span>Size ${size}</span><span>${money(s.price)}</span></div><div class="selection-row"><span>Nhân</span><span>${chosen('protein')||'Chưa chọn'}</span></div><div class="selection-row"><span>Sốt</span><span>${chosen('sauce')||'Chưa chọn'}</span></div>${s.base.length?`<div class="selection-row"><span>Đã gồm</span><span>${s.base.join(', ')}</span></div>`:''}${chosen('extra')?`<div class="selection-row"><span>Thêm</span><span>${chosen('extra')}</span></div>`:''}`;$('#total').textContent=money(C.total(size,selected));$('#add-taco').disabled=!isReady;$('#add-taco').innerHTML=isReady?`Thêm vào túi · ${money(C.total(size,selected))} <span>↗</span>`:'Chọn đủ nhân & sốt <span>↗</span>';const leftP=s.protein-C.count(selected,'protein'),leftS=s.sauce-C.count(selected,'sauce');$('#builder-status').textContent=isReady?'Đủ nhân & sốt rồi. Cuốn thôi!':`Còn ${leftP} phần nhân và ${leftS} phần sốt để hoàn thành.`;$('#board-message').style.opacity=Object.values(selected).some(n=>n>0)?'0':'';$('#board-bottom').textContent=isReady?'ĐÚNG GU BẠN. ĐÚNG CHẤT CHEESIE.':'THÊM TỪNG CHÚT NGON VÀO BÁNH';}
function renderTray(){const filtered=C.ingredients.filter(i=>i.kind===kind);$('#ingredient-tray').innerHTML=filtered.map(i=>`<div class="ingredient-card" draggable="true" data-ingredient="${i.id}">${icon(i)}<div class="ingredient-info"><strong>${i.name}</strong><small>${i.kind==='extra'?'+'+money(i.price):i.note||'Theo phần nhân của size'}</small><div class="stepper"><button aria-label="Bớt ${i.name}" data-minus="${i.id}" ${!selected[i.id]?'disabled':''}>−</button><span>${selected[i.id]||0}</span><button aria-label="Thêm ${i.name}" data-plus="${i.id}" ${!C.canAdd(size,selected,i.id)?'disabled':''}>+</button></div></div></div>`).join('');document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>add(b.dataset.plus));document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>remove(b.dataset.minus));document.querySelectorAll('[data-ingredient]').forEach(card=>{card.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',card.dataset.ingredient);e.dataTransfer.effectAllowed='copy';$('#dropzone').classList.add('dragover')});card.addEventListener('dragend',()=>$('#dropzone').classList.remove('dragover'))})}
function add(id){if(!C.canAdd(size,selected,id)){toast('Size '+size+' đã đủ phần này. Bạn có thể bớt một phần hoặc tăng size.');return}selected[id]=(selected[id]||0)+1;setFolded(false);update()}
function remove(id){if(selected[id])selected[id]--;setFolded(false);update()}
function changeSize(next){if(next===size)return;if(!C.fits(next,selected)){open(`<p class="eyebrow">ĐỔI SIZE TACOS</p><h2>Size nhỏ hơn,<br>chọn lại một chút nhé.</h2><p>Size ${next} có ${C.sizes[next].protein} phần nhân và ${C.sizes[next].sauce} phần sốt. Lựa chọn hiện tại vượt giới hạn. Đổi size sẽ xóa nhân và sốt đã chọn, giữ topping thêm.</p><div class="confirm-actions"><button class="button" id="cancel-size">Giữ size ${size}</button><button class="button burgundy" id="confirm-size">Đổi sang ${next}</button></div>`);$('#cancel-size').onclick=close;$('#confirm-size').onclick=()=>{selected=Object.fromEntries(Object.entries(selected).filter(([id])=>C.ingredients.find(i=>i.id===id).kind==='extra'));size=next;setFolded(false);update();close()};return}size=next;setFolded(false);update()}
function setFolded(value){folded=value;$('#dropzone').classList.toggle('folded',folded);$('#fold').textContent=folded?'Mở bánh để chỉnh sửa ↗':'Xem bánh đã cuốn ↗'}
function renderFood(){const s=C.sizes[size];let base='';s.base.forEach((name,n)=>{const i={color:name==='Mozzarella'?'#f4e5b6':name==='Trứng'?'#efb52f':'#ac5840',icon:name==='Mozzarella'?'cheese':name==='Trứng'?'egg':'bacon'};for(let k=0;k<(name==='Mozzarella'?10:3);k++){const a=k*2.4+n,x=250+Math.cos(a)*((k%3)*30+30),y=245+Math.sin(a)*((k%3)*30+30);base+=`<g transform="translate(${x-22} ${y-22}) rotate(${k*37} 22 22) scale(.8)">${svgContent(i)}</g>`}});$('#base-layer').innerHTML=base;let food='',sauce='',n=0;for(const i of C.ingredients){const amount=selected[i.id]||0;for(let portion=0;portion<amount;portion++){if(i.kind==='sauce'||i.sauceId){const off=n*8%55;sauce+=`<g class="food-piece"><path d="M${143+off} 170Q340 ${165+off} 170 210T335 255T165 302T330 340" stroke="${i.color}" stroke-width="${i.kind==='sauce'?8:5}" stroke-linecap="round" fill="none" opacity=".83" transform="rotate(${n*24%80-35} 250 250)"/></g>`;n++;continue}for(let k=0;k<5;k++){const a=(n*5+k)*2.39996,r=Math.sqrt(((n*5+k)%40)+1)*21,x=250+Math.cos(a)*r,y=250+Math.sin(a)*r;food+=`<g transform="translate(${x-25} ${y-25}) rotate(${(n*49+k*73)%360} 25 25) scale(.85)"><g class="food-piece">${svgContent(i)}</g></g>`}n++}}$('#food-layer').innerHTML=food;$('#sauce-layer').innerHTML=sauce}
const zone=$('#dropzone');zone.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';zone.classList.add('dragover')});zone.addEventListener('dragleave',e=>{if(!zone.contains(e.relatedTarget))zone.classList.remove('dragover')});zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragover');const id=e.dataTransfer.getData('text/plain');if(C.ingredients.some(i=>i.id===id))add(id)});
$('#fold').onclick=()=>{if(!C.ready(size,selected)&&!folded){toast('Bạn hãy chọn đủ nhân và sốt trước khi cuốn nhé.');return}setFolded(!folded)};$('#reset').onclick=()=>{if(!Object.values(selected).some(n=>n>0))return;open('<h2>Làm lại chiếc tacos?</h2><p>Xóa tất cả nhân, sốt và topping thêm. Size đang chọn được giữ lại.</p><button class="button burgundy" id="confirm-reset">Làm lại từ bánh trống</button>');$('#confirm-reset').onclick=()=>{selected={};setFolded(false);update();close()}};document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;document.querySelectorAll('[data-kind]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));update()});document.querySelectorAll('[data-kind]').forEach((b,n)=>b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const tabs=[...document.querySelectorAll('[data-kind]')],next=tabs[(n+(e.key==='ArrowRight'?1:2))%3];next.click();next.focus()}});
$('#add-taco').onclick=()=>{if(!C.ready(size,selected))return;const entries=Object.entries(selected).filter(([,v])=>v).sort(([a],[b])=>a.localeCompare(b));const details=`Nhân: ${chosen('protein')}. Sốt: ${chosen('sauce')}.${C.sizes[size].base.length?' Đã gồm: '+C.sizes[size].base.join(', ')+'.':''}${chosen('extra')?' Thêm: '+chosen('extra')+'.':''}`;addCart({key:'taco-'+size+'-'+JSON.stringify(entries)+'-'+$('#taco-note').value.trim(),name:'Tacos Pháp · size '+size,details:details+($('#taco-note').value.trim()?' Ghi chú: '+$('#taco-note').value.trim():''),price:C.total(size,selected)});setFolded(true)};
function renderMenu(){const favourites=['taco','burger-beef','chicken-1','fries'];const list=category==='favourites'?favourites.map(id=>C.menu.find(i=>i.id===id)):C.menu.filter(i=>i.category===category);$('#menu-grid').innerHTML=list.map(i=>`<article class="menu-card"><div class="dish-image">${i.image?`<img src="assets/${i.image}" alt="${i.id==='taco'?'Tacos từ ảnh menu Cheesie':i.image==='burger.jpg'?'Ảnh burger đại diện từ menu Cheesie':i.name+' từ menu Cheesie'}" loading="lazy">`:`<div class="menu-art ${i.category}" aria-hidden="true">${i.emoji}</div>`}${i.tag?`<span>${i.tag}</span>`:''}</div><div class="menu-card-text"><h3>${i.name}</h3><p>${i.desc}</p><div class="dish-bottom"><strong>${i.id==='taco'?'Từ ':''}${money(i.price)}</strong><button class="dish-add" data-dish="${i.id}" aria-label="${i.id==='taco'?'Tự chọn':'Chọn'} ${i.name}">+</button></div></div></article>`).join('');document.querySelectorAll('[data-dish]').forEach(b=>b.onclick=()=>{const item=C.menu.find(i=>i.id===b.dataset.dish);if(item.id==='taco'){$('#builder').scrollIntoView({behavior:'smooth'});return}showDish(item)})}
function showDish(item){let qty=1;open(`<span class="menu-badge">MENU CHEESIE</span><h2>${item.name}</h2><p>${item.desc}</p><p>Giá một phần: <strong>${money(item.price)}</strong></p><div class="quantity-select"><button id="qty-minus" aria-label="Bớt số lượng">−</button><strong id="qty">1</strong><button id="qty-plus" aria-label="Thêm số lượng">+</button></div><label for="dish-note">Ghi chú món / vị sốt mong muốn</label><input class="note-input" id="dish-note" maxlength="200" placeholder="Ví dụ: ít cay, sốt BBQ…"><p>Yêu cầu riêng và vị sốt cần được quán xác nhận.</p><button class="button burgundy" id="add-dish">Thêm vào túi · ${money(item.price)}</button>`);function q(){ $('#qty').textContent=qty;$('#qty-minus').disabled=qty===1;$('#qty-plus').disabled=qty===20;$('#add-dish').textContent='Thêm vào túi · '+money(qty*item.price)}$('#qty-minus').onclick=()=>{if(qty>1)qty--;q()};$('#qty-plus').onclick=()=>{if(qty<20)qty++;q()};q();$('#add-dish').onclick=()=>{const note=$('#dish-note').value.trim();const row={key:item.id+'-'+note,name:item.name,details:note,price:item.price};const old=cart.find(r=>r.key===row.key);if(old)old.qty=Math.min(99,old.qty+qty);else cart.push({...row,qty});saveCart();close();toast('Đã thêm '+item.name+' vào túi!')}}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('selected',x===b));renderMenu()});
function cartTotal(){return cart.reduce((n,r)=>n+r.price*r.qty,0)}
function showCart(){open(`<p class="eyebrow">YOUR GOOD FOOD BAG</p><h2>Túi đồ ngon của bạn.</h2>${cart.length?cart.map((r,n)=>`<div class="cart-item"><div><span>${escapeHTML(r.name)}</span><span>${money(r.price*r.qty)}</span></div>${r.details?`<p>${escapeHTML(r.details)}</p>`:''}<div class="cart-controls"><button data-qty="${n}" data-delta="-1" aria-label="Bớt ${escapeHTML(r.name)}">−</button><span>${r.qty}</span><button data-qty="${n}" data-delta="1" aria-label="Thêm ${escapeHTML(r.name)}" ${r.qty>=99?'disabled':''}>+</button><button data-delete="${n}">Xóa món</button></div></div>`).join('')+`<div class="cart-total"><span>Tạm tính</span><span>${money(cartTotal())}</span></div><p>Chưa gồm phí giao hàng. Giá và tình trạng món cần được quán xác nhận. Túi món chưa được gửi đi.</p><button class="button burgundy" id="review-order">Xem nội dung & chọn kênh đặt ↗</button>`:'<p>Túi đang trống. Một chiếc tacos đúng gu đang đợi bạn.</p><button class="button burgundy" id="back-builder">Tự cuốn tacos ↗</button>'}`);document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.qty);cart[n].qty+=Number(b.dataset.delta);if(cart[n].qty<=0)cart.splice(n,1);saveCart();showCart()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.delete),1);saveCart();showCart()});if($('#review-order'))$('#review-order').onclick=()=>channels(true);if($('#back-builder'))$('#back-builder').onclick=()=>{close();$('#builder').scrollIntoView({behavior:'smooth'})}}
function orderText(){return 'Chào Cheesie, mình muốn đặt:\n'+cart.map((r,n)=>`${n+1}. ${r.qty} × ${r.name} — ${money(r.price*r.qty)}${r.details?'\n   '+r.details:''}`).join('\n')+'\nTạm tính: '+money(cartTotal())+'\nChưa gồm phí giao hàng. Nhờ quán xác nhận món, giá và thời gian giúp mình nhé.'}
const links={facebook:'https://www.facebook.com/profile.php?id=61560992384243',shopee:'https://shopeefood.vn/can-tho/cheesie-tacos-burger-le-lai',grab:'https://food.grab.com/vn/vi/restaurant/cheesie-l%C3%AA-lai-delivery/5-C72BC3LUTTU3G2'};
function channels(withOrder=false){open(`<p class="eyebrow">ĐẶT MÓN CÙNG CHEESIE</p><h2>Chốt gu rồi,<br>chọn nơi đặt nhé.</h2>${withOrder?'<label for="order-copy">Nội dung đơn để sao chép</label><textarea class="order-text" id="order-copy" readonly></textarea><button class="button burgundy" id="copy-order">Sao chép nội dung đơn ↗</button>':''}<div class="channels"><a class="channel" href="${links.facebook}" target="_blank" rel="noopener noreferrer"><strong>Facebook</strong><small>Mở trang quán để gửi nội dung đơn ↗</small></a><a class="channel" href="${links.shopee}" target="_blank" rel="noopener noreferrer"><strong>ShopeeFood</strong><small>Mở gian hàng Cheesie ↗</small></a><a class="channel" href="${links.grab}" target="_blank" rel="noopener noreferrer"><strong>GrabFood</strong><small>Mở gian hàng Cheesie ↗</small></a></div><p>Chưa có đơn nào được gửi từ website. Bạn có thể sao chép nội dung và gửi cho quán qua Facebook để xác nhận. Công thức tacos không tự đồng bộ sang ShopeeFood hoặc GrabFood; cần chọn lại món trên ứng dụng.</p>${withOrder?'<button class="button" id="back-cart">← Quay lại túi món</button>':''}`);if(withOrder){$('#order-copy').value=orderText();$('#copy-order').onclick=async()=>{try{await navigator.clipboard.writeText($('#order-copy').value);toast('Đã sao chép. Bạn chưa gửi đơn đến quán.')}catch{$('#order-copy').focus();$('#order-copy').select();toast('Nội dung đã được chọn. Bạn có thể sao chép thủ công.')}};$('#back-cart').onclick=showCart}}
function menuOriginal(){open('<p class="eyebrow">TỪ MENU BẠN CUNG CẤP</p><h2>Menu nhà Cheesie.</h2><p class="original-menu-caption">Giá trên bản menu được cung cấp; cần quán xác nhận trước khi mở nhận đơn thật. Ảnh sản phẩm trên website được cắt từ menu và dùng đại diện cho nhóm món.</p><img class="original-menu" src="assets/menu.jpg" alt="Menu gốc Cheesie: tacos, gà tender, burger, khoai, mì Ý và đồ uống"><img class="original-menu" src="assets/combos.jpg" alt="Menu combo Cheesie gồm Chicken and Fries 99k, Best Seller 119k, Bestie 159k, Signature Mega 219k và Big Feast 315k">')}
$('#view-menu').onclick=menuOriginal;$('#footer-menu').onclick=menuOriginal;$('#open-bag').onclick=showCart;$('#order-channels').onclick=()=>channels(false);$('#restaurant-info').onclick=()=>open('<p class="eyebrow">GHÉ NHÀ CHEESIE</p><h2>Trạm dừng tiếp theo:<br>Cheesie.</h2><img class="original-menu" src="assets/interior.jpg" alt="Không gian chỗ ngồi trong quán Cheesie"><p><strong>102 Đ. Lê Lai, Ninh Kiều, Cần Thơ</strong><br>Mở cửa: 9:30–22:30<br><a href="tel:0788786283">078 878 6283</a><br><a href="mailto:cheesieburgersandtacos@gmail.com">cheesieburgersandtacos@gmail.com</a></p><a class="button burgundy" href="https://www.google.com/maps/search/?api=1&query=102%20L%C3%AA%20Lai%20Ninh%20Ki%E1%BB%81u%20C%E1%BA%A7n%20Th%C6%A1" target="_blank" rel="noopener noreferrer">Mở bản đồ ↗</a><p>Thông tin do quán cung cấp.</p>');saveCart();renderMenu();update();
